css:
/*
 * @artisanpack-ui/tokens preset "lemon".
 * Brand preset generated from #ffee00 by apui-generate-preset.
 * Generated by apui-generate-preset. Regenerate rather than edit by hand.
 */
@layer apui.tokens {
  [data-preset="lemon"] {
    --apui-steel-50: #fbf9ae;
    --apui-steel-100: #ffee00;
    --apui-steel-200: #e7dc00;
    --apui-steel-300: #d0c500;
    --apui-steel-400: #b1a900;
    --apui-steel-500: #948c00;
    --apui-steel-600: #7b7400;
    --apui-steel-700: #625d00;
    --apui-steel-800: #4b4700;
    --apui-steel-900: #343100;
    --apui-steel-950: #222000;
    --apui-slate-50: #fef2f2;
    --apui-slate-100: #fee3e4;
    --apui-slate-200: #ffcad0;
    --apui-slate-300: #ffaab7;
    --apui-slate-400: #fe7b91;
    --apui-slate-500: #ff0066;
    --apui-slate-600: #e10057;
    --apui-slate-700: #b70041;
    --apui-slate-800: #8d0034;
    --apui-slate-900: #660023;
    --apui-slate-950: #470016;
  }

  [data-preset="lemon"],
  [data-preset="lemon"][data-theme="light"],
  [data-theme="light"] [data-preset="lemon"],
  [data-preset="lemon"] [data-theme="light"] {
    --apui-focus-ring-color: var(--apui-steel-600);
    --apui-selected-bg: var(--apui-color-primary-soft);
    --apui-selected-border: var(--apui-color-primary-border);
    --apui-syntax-keyword: var(--apui-steel-700);
    --apui-color-primary: var(--apui-steel-600);
    --apui-color-primary-hover: var(--apui-steel-700);
    --apui-color-primary-soft: var(--apui-steel-100);
    --apui-color-primary-soft-foreground: var(--apui-steel-700);
    --apui-color-primary-border: var(--apui-steel-600);
    --apui-color-primary-text: var(--apui-steel-700);
    --apui-color-secondary: var(--apui-slate-600);
    --apui-color-secondary-hover: var(--apui-slate-700);
    --apui-color-secondary-soft: var(--apui-slate-100);
    --apui-color-secondary-soft-foreground: var(--apui-slate-700);
    --apui-color-secondary-border: var(--apui-slate-600);
    --apui-color-secondary-text: var(--apui-slate-700);
  }

  [data-preset="lemon"][data-theme="dark"],
  [data-theme="dark"] [data-preset="lemon"],
  [data-preset="lemon"] [data-theme="dark"] {
    --apui-focus-ring-color: var(--apui-steel-300);
    --apui-selected-bg: var(--apui-color-primary-soft);
    --apui-selected-border: var(--apui-color-primary-border);
    --apui-syntax-keyword: var(--apui-steel-300);
    --apui-color-primary: var(--apui-steel-400);
    --apui-color-primary-hover: var(--apui-steel-300);
    --apui-color-primary-soft: var(--apui-steel-900);
    --apui-color-primary-soft-foreground: var(--apui-steel-300);
    --apui-color-primary-border: var(--apui-steel-500);
    --apui-color-primary-text: var(--apui-steel-400);
    --apui-color-secondary: var(--apui-slate-400);
    --apui-color-secondary-hover: var(--apui-slate-300);
    --apui-color-secondary-soft: var(--apui-slate-900);
    --apui-color-secondary-soft-foreground: var(--apui-slate-300);
    --apui-color-secondary-border: var(--apui-slate-500);
    --apui-color-secondary-text: var(--apui-slate-400);
  }

  [data-preset="lemon"][data-theme="high-contrast"],
  [data-theme="high-contrast"] [data-preset="lemon"],
  [data-preset="lemon"] [data-theme="high-contrast"] {
    --apui-focus-ring-color: var(--apui-steel-800);
    --apui-selected-bg: var(--apui-color-primary-soft);
    --apui-selected-border: var(--apui-color-primary-border);
    --apui-syntax-keyword: var(--apui-steel-800);
    --apui-color-primary: var(--apui-steel-800);
    --apui-color-primary-hover: var(--apui-steel-900);
    --apui-color-primary-soft: var(--apui-steel-50);
    --apui-color-primary-soft-foreground: var(--apui-steel-900);
    --apui-color-primary-border: var(--apui-steel-800);
    --apui-color-primary-text: var(--apui-steel-800);
    --apui-color-secondary: var(--apui-slate-800);
    --apui-color-secondary-hover: var(--apui-slate-900);
    --apui-color-secondary-soft: var(--apui-slate-50);
    --apui-color-secondary-soft-foreground: var(--apui-slate-900);
    --apui-color-secondary-border: var(--apui-slate-800);
    --apui-color-secondary-text: var(--apui-slate-800);
  }
}
